from typing import TYPE_CHECKING

from taf.internal.aliasing import AliasLookupError
from taf.transport.ssh import ssh

from ..pylogger.logger import log_input_and_output, log_operation, log_result, log_suppression
from .reconnection import force_reconnect_while_not_connected

if TYPE_CHECKING:
    from taf.transport.ssh.session import SSHSession  # noqa: F401


class Device(object):

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self):
        self._ssh = ssh()
        self._alias = None

    @log_input_and_output
    def force_reconnect(self):
        """
        Forces device to reconnect based on device's alias.
        """
        self._ssh.force_reconnect(connection=self._alias)

    @log_input_and_output
    def is_connected(self):
        """
        Performs simple connection checks via device's alias with connection stored in session cache.

        :return: True if connection is not dead, False otherwise.
        :rtype: bool
        """
        con = self.get_connection_by_alias(self._alias)
        return con.is_connected

    @log_input_and_output
    def reset_cache(self):
        """
        Resets all connections from cache (e.g. in order to build new connection to device).
        """
        self._ssh.reset_cache()

    @log_input_and_output
    def get_alias(self):
        """
        Returns alias of device.

        :return: alias
        :rtype: str
        """
        return self._alias

    @log_input_and_output
    @force_reconnect_while_not_connected
    def download_file(self, local_path, remote_path):
        """
        Downloads file from device via ssh.

        :param local_path: Path where file will be saved.
        :type  local_path: str
        :param remote_path: Path to file on device.
        :type  remote_path: str
        """

        log_operation("Downloading file from {} on {}, to {}".format(remote_path, self._alias, local_path))

        self._ssh.download_file(remote_path, local_path, self._alias)

        log_result("Download file from {} on {}, to {}".format(remote_path, self._alias, local_path))

    @log_input_and_output
    @force_reconnect_while_not_connected
    def upload_file(self, local_path, remote_path):
        """
        Uploads file to device.

        :param local_path: Path to file which will be uploaded.
        :type  local_path: str
        :param remote_path: Path to file on device.
        :type  remote_path: str
        """
        log_operation("Uploading file from {} on PC, to {} on {}".format(local_path, remote_path, self._alias))

        self._ssh.upload_file(local_path, remote_path, self._alias)

        log_result("Uploaded file from {} on PC, to {} on {}".format(local_path, remote_path, self._alias))

    @log_input_and_output
    @force_reconnect_while_not_connected
    def execute(self, command, timeout=None):
        """
        Sends a command to the remote using the instance designated by the
        connection parameter, waits for the execution to finish, and returns
        the outputs' contents (both stdout and stdin).

        :param command: The linux command.
        :type command: str
        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        :type timeout: str or int
        """
        device = self.get_alias()

        log_operation("Executing command: {} on {}".format(command, device))

        result = self._ssh.execute(command, device, timeout)

        log_result("Command: {} executed on {}".format(command, device))

        return result

    @log_input_and_output
    @force_reconnect_while_not_connected
    def send_command(self, command, timeout=None):
        """
        Sends a command to the remote using the instance designated by the
        connection parameter.

        :param command: The linux command.
        :type command: str
        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        :type timeout: str or int
        """
        device = self.get_alias()

        log_operation("Sending command: {} to {}".format(command, device))

        self._ssh.send_command(command=command, connection=device, timeout=timeout)

        log_result("Command: {} sent to {}".format(command, device))

    @log_input_and_output
    @force_reconnect_while_not_connected
    def read_output(self):
        """
        Reads stdout from the device.

        :return: read stdout from provided device.
        :rtype: str
        """
        device = self.get_alias()

        log_operation("Reading output from {}".format(device))

        result = self._ssh.read_output(connection=device)

        log_result("Output read from {}: {}".format(device, result))

        return result

    @log_input_and_output
    @force_reconnect_while_not_connected
    def file_exists(self, remote_path, timeout=None):
        """
        Checks if file exists under provided remote path.

        :param remote_path:
        :type remote_path: str
        :param timeout: (optional) Timeout for keyword execution, None by
            default. Accepts a timeout string in Robot Framework format.
            If None, waits for the command to end indefinitely.
        :type timeout: str or int
        :return: True if file exists, False otherwise.
        :rtype: Bool
        """
        device = self.get_alias()

        log_operation(
            "Checking if file exist on {0} device under path {1}".format(
                device, remote_path
            )
        )

        result = self._ssh.file_exists(
            remote_path=remote_path, connection=device, timeout=timeout
        )

        log_result("Status of file checking on {0} device under path {1}: {2}".format(device, remote_path, result))

        return result

    @log_input_and_output
    def get_connection_by_alias(self, alias=None):
        """
        Returns a connection instance bound to the given alias.

        :param alias: Name of device.
        :type alias: str
        :return: connection
        :rtype: instance of connection
        """
        return self._ssh.get_connection_by_alias(alias)

    @log_input_and_output
    def close_connection(self):
        """
        Closes connection with device.
        """
        self._close_connection(device=self.get_alias())

    @log_input_and_output
    def close_inner_connection(self, inner_alias=None):
        """
        Closes inner connection opened by this device.

        :param inner_alias: Alias to proxy connection if user wishes to close connection to inner alias instead
                            of closing connection to device that performs SSH operations (e.g. SMODs containers).
        type inner_alias: str or None

        """
        self._close_connection(device=inner_alias)

    @log_input_and_output
    def get_list_of_files_in_directory(self, directory):
        """
        Returns a list the files and directories within the specified directory.

        :param directory: path to directory
        :type directory: str
        :return: list of files and directories
        :rtype: list of str
        """
        log_operation('Reading contents of directory: {}.'.format(directory))
        self.send_command(command='ls {}'.format(directory))

        files_list = self.read_output()
        files_list = [file_name.strip() for file_name in files_list.split('\n') if file_name.strip()]

        return files_list

    @log_input_and_output
    def _close_connection(self, device):
        try:
            self._ssh.disconnect(device)
            log_result("Connection with {} via ssh closed successfully".format(device))

        except AliasLookupError as e:
            log_suppression('During connection closing following exception was ignored: {}'.format(e))

    @log_input_and_output
    def _connect_to(
        self, hostname, username, password=None, proxy=None, alias=None, timeout=30.0
    ):
        """
        Connects to device via ssh.

        :param hostname: The hostname of the remote to connect to.
        :type hostname: str
        :param username: Username that should be used in authentication.
        :type username: str
        :param password: Password that will be used in authentication and to try to decrypt the
            private key if needed.
        :type password: str, optional
        :param proxy: Opened connection to the remote host, from which the new
            connection will be started.
        :type proxy: Connection, optional
        :param alias: Name of device
        :type alias: str
        :param timeout: Timeout in seconds for the TCP connect (None by default).
            Also used in initiating the file protocol client ('files' property of
            the returned instance).
        :type timeout: float, optional
        :return: SSH connection instance
        :rtype: SSHSession
        """
        self._alias = alias if alias else self.__get_device()
        connection = self._ssh.connect_to(
            hostname=hostname,
            username=username,
            password=password,
            proxy=proxy,
            alias=self._alias,
            timeout=timeout,
        )

        log_result("Connected with {} via ssh".format(self._alias))
        return connection

    @classmethod
    def __get_device(cls):
        return cls.__name__
